        EmailPeer::addSelectColumns($criteria);
        $startcol2 = EmailPeer::NUM_HYDRATE_COLUMNS;

        EmailAccountPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + EmailAccountPeer::NUM_HYDRATE_COLUMNS;

        EmailEstadoPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + EmailEstadoPeer::NUM_HYDRATE_COLUMNS;

        ModuloPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + ModuloPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(EmailPeer::EMAILACCOUNT_ID, EmailAccountPeer::EMAILACCOUNT_ID, $join_behavior);

        $criteria->addJoin(EmailPeer::EMAILESTADO_ID, EmailEstadoPeer::EMAILESTADO_ID, $join_behavior);

        $criteria->addJoin(EmailPeer::MODULO_ID, ModuloPeer::MODULO_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseEmailPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = EmailPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = EmailPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = EmailPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                EmailPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined EmailAccount rows

                $key2 = EmailAccountPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = EmailAccountPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = EmailAccountPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    EmailAccountPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (Email) to the collection in $obj2 (EmailAccount)
                $obj2->addEmail($obj1);

            } // if joined row is not null

                // Add objects for joined EmailEstado rows

                $key3 = EmailEstadoPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = EmailEstadoPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = EmailEstadoPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    EmailEstadoPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (Email) to the collection in $obj3 (EmailEstado)
                $obj3->addEmail($obj1);

            } // if joined row is not null

                // Add objects for joined Modulo rows

                $key4 = ModuloPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = ModuloPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = ModuloPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    ModuloPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (Email) to the collection in $obj4 (Modulo)
                $obj4->addEmail($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


