                $obj1 = new $cls();
                $obj1->hydrate($row);
                EmailPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined EmailAccount rows

                $key2 = EmailAccountPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
